146	
147	export interface StopRuleState {
148	  pairs: number;
149	  /** Discordant pairs NEW won (NEW passed, OLD failed) and lost. */
150	  won: number;
151	  lost: number;
152	  triggered: boolean;
153	}
154	
155	export function evaluateStopRule(pairs: ForwardPair[]): StopRuleState {
156	  const won = pairs.filter((p) => p.pass_new && !p.pass_old).length;
157	  const lost = pairs.filter((p) => !p.pass_new && p.pass_old).length;
158	  return { pairs: pairs.length, won, lost, triggered: pairs.length >= MIN_PAIRS && lost - won >= MIN_NET_LOSSES };
159	}
