171	/** Opens the revert PR through src/act when it exists; until then it is a logged stub. */
172	export async function defaultOpenRevertPr(req: RevertRequest): Promise<RevertOutcome> {
173	  const spec = "../act/index.ts";
174	  if (existsSync(join(import.meta.dir, spec))) {
175	    const mod = (await import(spec)) as { openRevertPr?: (r: RevertRequest) => Promise<{ url?: string | null }> };
176	    if (mod.openRevertPr) return { url: (await mod.openRevertPr(req)).url ?? null, stub: false };
177	  }
178	  return { url: null, stub: true };
